.wc-dl-card{
  display:flex;align-items:center;gap:18px;
  background:#fff;border:1px solid #e6ecf3;border-radius:12px;
  padding:22px;text-decoration:none;color:inherit;
  max-width:560px;
  transition:transform .2s,box-shadow .2s,border-color .2s;
}
.wc-dl-card:hover{
  transform:translateY(-3px);
  box-shadow:0 14px 32px rgba(31,45,61,.10);
  border-color:#6B86A1;color:inherit;text-decoration:none;
}
.wc-dl-icon{
  flex:0 0 56px;width:56px;height:68px;
  background:linear-gradient(135deg,#6B86A1,#3a5774);
  color:#fff;border-radius:8px;
  display:flex;align-items:center;justify-content:center;
  font-weight:700;font-size:.72rem;letter-spacing:.05em;
  position:relative;box-shadow:0 6px 14px rgba(107,134,161,.35);
}
.wc-dl-icon::after{
  content:"";position:absolute;top:0;right:0;
  width:14px;height:14px;
  background:linear-gradient(225deg,#fff 50%,transparent 50%);
  border-radius:0 8px 0 4px;
}
.wc-dl-body{flex:1;min-width:0;}
.wc-dl-body .t{font-size:1.05rem;font-weight:600;color:#1f2d3d;margin:0 0 4px;line-height:1.3;}
.wc-dl-body .m{font-size:.85rem;color:#6b7c8e;margin:0;}
.wc-dl-arrow{color:#6B86A1;font-size:1.6rem;font-weight:300;transition:transform .2s;}
.wc-dl-card:hover .wc-dl-arrow{transform:translateX(4px);}

